// Фикстура тестов текста в сцене (tests/agent/highlevel_text_test.py).
//
// Текст здесь рисуется подсистемой шрифтов движка (stb_truetype → атлас →
// спрайты в общем батче), а не очередью поверх сцены. Шрифт грузится по
// абсолютному пути, который тест передаёт через engine.fs перед стартом:
// фикстура обязана работать и без ассетов рядом.
$.ready(() => {
    $.world.gravity(0, 0).color('#000000').bounds(0, 0, 640, 360);

    // Мировой текст: мировой кегль, камера применяет зум масштабом.
    $('<text>', { id: 'world', text: 'Привет, мир', size: 24 })
        .at(320, 120).appendTo($.world);

    // UI-текст: координаты окна, отдельный слой.
    $('<ui.label>', { id: 'hud', text: 'HP 100', size: 20 })
        .at(60, 30).appendTo($.ui);

    // Кнопка: подпись рисуется цветом text_color.
    $('<ui.button>', { id: 'go', text: 'Играть', w: 160, h: 44 })
        .at(320, 260).appendTo($.ui);

    // Своё семейство шрифта у узла и наследование детьми. Пишем в globalThis,
    // а не в window: в QuickJS объекта window нет, и обращение к нему роняло
    // весь $.ready (ошибка была видна только в stderr движка).
    globalThis.__fontFamily = null;
});
